{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_D2C_Funnel_Metrics AS WITH Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, t.Metric as Type, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM `MapleMonk.Zouk_d2c_Targets` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ) , DTC_PandL AS ( SELECT Date(Date) AS Date, Channel, CASE WHEN lower(Channel) like \'website\' THEN \'WEBSITE\' ELSE \'APP\' END AS Final_Marketplace, sum(Orders) AS Total_Orders, sum(Net_Revenue) AS Net_Revenue, sum(Repeat_Customer_Sale) AS Repeat_Customer_Sale, sum(quantity) AS Quantity, sum(CM_2) AS CM_2, sum(GM) AS GM, sum(web_Sessions) AS Web_Sessions, sum(App_Sessions) AS App_Sessions, sum(ifnull(brand_spend,0))-sum(ifnull(spend,0))-sum(ifnull(other_perf_spend,0)) AS Perf_Spend FROM `MapleMonk.Zouk_D2C_Sessions_Report` GROUP BY 1,2,3 ) , Metric_Revenue AS ( SELECT t.Date, \'Net Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() THEN d.Net_Revenue ELSE 0 END) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'net revenue\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ) , Metric_Perf_SPend AS ( SELECT t.Date, \'Perf. Marketing %\' AS Metric, t.Daily_Target * 100 AS Target, t.days_remaining, t.no_of_days, sum(ifnull(perf_spend,0)) AS Numerator, sum(ifnull(net_revenue,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'perf%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_CM AS ( SELECT t.Date, \'CM%\' AS Metric, t.Daily_Target * 100 AS Target, t.days_remaining, t.no_of_days, sum(ifnull(cm_2,0)) AS Numerator, sum(ifnull(net_revenue,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%cm%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Traffic AS ( SELECT t.Date, \'Website Sessions\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() THEN Web_Sessions else 0 end) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%website sessions%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Conversion AS ( SELECT t.Date, \'Conversion Rate %\' AS Metric, t.Daily_Target * 100 AS Target, t.days_remaining, t.no_of_days, sum(ifnull(d.total_orders,0)) AS Numerator, sum(ifnull(d.Web_Sessions,0))+ sum(ifnull(d.app_Sessions,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'conversion%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Aov AS ( SELECT t.Date, \'AOV\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, sum(ifnull(d.Net_Revenue,0)) AS Numerator, sum(ifnull(d.total_orders,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%aov%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Repeat AS ( SELECT t.Date, \'Repeat Net Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() THEN d.repeat_customer_sale ELSE 0 END) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%repeat%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_App AS ( SELECT t.Date, \'App Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, sum(case when lower(d.final_marketplace) = \'app\' then d.Net_Revenue end) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'app net%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_GM AS ( SELECT t.Date, \'Gross Margin %\' AS Metric, t.Daily_Target * 100 AS Target, t.days_remaining, t.no_of_days, sum(ifnull(d.gm,0)) AS Numerator, sum(ifnull(d.Net_Revenue,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%gm%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Web_Repeat AS ( SELECT t.Date, \'Website Repeat\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(case when lower(d.channel) like \'website\' then d.Net_Revenue end) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'website repeat%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_app_Repeat AS ( SELECT t.Date, \'App Repeat\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(case when lower(d.final_marketplace) like \'app\' then d.Repeat_Customer_Sale end) AS Numerator, 1 AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'app repeat%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ) SELECT * FROM Metric_Revenue UNION ALL SELECT * FROM Metric_Perf_SPend UNION ALL SELECT * FROM Metric_CM UNION ALL SELECT * FROM Metric_Traffic UNION ALL SELECT * FROM Metric_Conversion UNION ALL SELECT * FROM Metric_aov UNION ALL SELECT * FROM Metric_repeat UNION ALL SELECT * FROM Metric_app UNION ALL SELECT * FROM Metric_gm UNION ALL SELECT * FROM Metric_web_repeat UNION ALL SELECT * from Metric_app_repeat ORDER BY Date, Metric ; CREATE OR REPLACE TABLE MapleMonk.zouk_D2c_Weekly_Funnel_Metrics AS WITH Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, t.Metric as Type, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM `MapleMonk.Zouk_d2c_weekly_Targets` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), DTC_PandL AS ( SELECT Date(Date) AS Date, Channel, CASE WHEN lower(Channel) like \'website\' THEN \'WEBSITE\' ELSE \'APP\' END AS Final_Marketplace, sum(Orders) AS Total_Orders, sum(Net_Revenue) AS Net_Revenue, sum(Repeat_Customer_Sale) AS Repeat_Customer_Sale, sum(quantity) AS Quantity, sum(CM_2) AS CM_2, sum(GM) AS GM, sum(web_Sessions) AS Web_Sessions, sum(App_Sessions) AS App_Sessions, sum(ifnull(brand_spend,0))-sum(ifnull(spend,0))-sum(ifnull(other_perf_spend,0)) AS Perf_Spend FROM `MapleMonk.Zouk_D2C_Sessions_Report` GROUP BY 1,2,3 ), Metric_Conversion AS ( SELECT t.Date, \'Conversion Rate %\' AS Metric, t.Daily_Target * 100 AS Target, sum(ifnull(d.total_orders,0)) AS Numerator, sum(ifnull(d.Web_Sessions,0))+ sum(ifnull(d.app_Sessions,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'conversion%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_UPT AS ( SELECT t.Date, \'UPT\' AS Metric, t.Daily_Target AS Target, sum(ifnull(d.quantity,0)) AS Numerator, sum(ifnull(d.total_orders,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'upt\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_ASP AS ( SELECT t.Date, \'ASP\' AS Metric, t.Daily_Target AS Target, sum(ifnull(d.net_revenue,0)) AS Numerator, sum(ifnull(d.quantity,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'asp\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_AOV AS ( SELECT t.Date, \'AOV\' AS Metric, t.Daily_Target AS Target, sum(ifnull(d.net_revenue,0)) AS Numerator, sum(ifnull(d.total_orders,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'aov\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_Repeat_Revenue AS ( SELECT t.Date, \'Repeat Net Revenue\' AS Metric, t.Daily_Target AS Target, sum(ifnull(d.repeat_customer_sale,0)) AS Numerator, null AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'repeat net%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_App_Revenue AS ( SELECT t.Date, \'App Revenue\' AS Metric, t.Daily_Target AS Target, sum(case when lower(channel) like any (\'android\',\'ios\') then Net_Revenue else 0 end) AS Numerator, null AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'app%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ), Metric_GM AS ( SELECT t.Date, \'GM %\' AS Metric, t.Daily_Target * 100 AS Target, sum(ifnull(d.gm,0)) AS Numerator, sum(ifnull(d.net_revenue,0)) AS Denominator FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'gm%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3 ) SELECT * FROM Metric_Conversion UNION ALL SELECT * FROM Metric_ASP UNION ALL SELECT * FROM Metric_UPT UNION ALL SELECT * FROM Metric_AOV UNION ALL SELECT * FROM Metric_Repeat_Revenue UNION ALL SELECT * FROM Metric_APP_Revenue UNION ALL SELECT * FROM metric_GM ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

